//  FSM Module
// ------------------------------------------------------------------


module esp_acc_DUMMY_LeakyreluController_acc2dma_acc2dma_acc2dma_fsm (
  clk, rst, acc2dma_wen, fsm_output, while_C_2_tr0, while_for_for_C_0_tr0, while_for_C_2_tr0
);
  input clk;
  input rst;
  input acc2dma_wen;
  output [8:0] fsm_output;
  reg [8:0] fsm_output;
  input while_C_2_tr0;
  input while_for_for_C_0_tr0;
  input while_for_C_2_tr0;


  // FSM State Type Declaration for esp_acc_DUMMY_LeakyreluController_acc2dma_acc2dma_acc2dma_fsm_1
  parameter
    acc2dma_rlp_C_0 = 4'd0,
    while_C_0 = 4'd1,
    while_C_1 = 4'd2,
    while_C_2 = 4'd3,
    while_for_C_0 = 4'd4,
    while_for_C_1 = 4'd5,
    while_for_for_C_0 = 4'd6,
    while_for_C_2 = 4'd7,
    while_C_3 = 4'd8;

  reg [3:0] state_var;
  reg [3:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : esp_acc_DUMMY_LeakyreluController_acc2dma_acc2dma_acc2dma_fsm_1
    case (state_var)
      while_C_0 : begin
        fsm_output = 9'b000000010;
        state_var_NS = while_C_1;
      end
      while_C_1 : begin
        fsm_output = 9'b000000100;
        state_var_NS = while_C_2;
      end
      while_C_2 : begin
        fsm_output = 9'b000001000;
        if ( while_C_2_tr0 ) begin
          state_var_NS = while_C_3;
        end
        else begin
          state_var_NS = while_for_C_0;
        end
      end
      while_for_C_0 : begin
        fsm_output = 9'b000010000;
        state_var_NS = while_for_C_1;
      end
      while_for_C_1 : begin
        fsm_output = 9'b000100000;
        state_var_NS = while_for_for_C_0;
      end
      while_for_for_C_0 : begin
        fsm_output = 9'b001000000;
        if ( while_for_for_C_0_tr0 ) begin
          state_var_NS = while_for_C_2;
        end
        else begin
          state_var_NS = while_for_for_C_0;
        end
      end
      while_for_C_2 : begin
        fsm_output = 9'b010000000;
        if ( while_for_C_2_tr0 ) begin
          state_var_NS = while_C_3;
        end
        else begin
          state_var_NS = while_for_C_0;
        end
      end
      while_C_3 : begin
        fsm_output = 9'b100000000;
        state_var_NS = while_C_0;
      end
      // acc2dma_rlp_C_0
      default : begin
        fsm_output = 9'b000000001;
        state_var_NS = while_C_0;
      end
    endcase
  end

  always @(posedge clk or negedge rst) begin
    if ( ~ rst ) begin
      state_var <= acc2dma_rlp_C_0;
    end
    else if ( acc2dma_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

