// ------------------------------------------------------------------
//  Design Unit:    esp_acc_DUMMY_LeakyreluController_plm2vec_plm2vec_plm2vec_fsm
//  FSM Module
// ------------------------------------------------------------------


module esp_acc_DUMMY_LeakyreluController_plm2vec_plm2vec_plm2vec_fsm (
  clk, rst, plm2vec_wen, fsm_output, while_C_0_tr0, while_for_C_0_tr0, while_for_for_C_5_tr0,
      while_for_C_1_tr0
);
  input clk;
  input rst;
  input plm2vec_wen;
  output [10:0] fsm_output;
  reg [10:0] fsm_output;
  input while_C_0_tr0;
  input while_for_C_0_tr0;
  input while_for_for_C_5_tr0;
  input while_for_C_1_tr0;


  // FSM State Type Declaration for esp_acc_DUMMY_LeakyreluController_plm2vec_plm2vec_plm2vec_fsm_1
  parameter
    plm2vec_rlp_C_0 = 4'd0,
    while_C_0 = 4'd1,
    while_for_C_0 = 4'd2,
    while_for_for_C_0 = 4'd3,
    while_for_for_C_1 = 4'd4,
    while_for_for_C_2 = 4'd5,
    while_for_for_C_3 = 4'd6,
    while_for_for_C_4 = 4'd7,
    while_for_for_C_5 = 4'd8,
    while_for_C_1 = 4'd9,
    while_C_1 = 4'd10;

  reg [3:0] state_var;
  reg [3:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : esp_acc_DUMMY_LeakyreluController_plm2vec_plm2vec_plm2vec_fsm_1
    case (state_var)
      while_C_0 : begin
        fsm_output = 11'b00000000010;
        if ( while_C_0_tr0 ) begin
          state_var_NS = while_C_1;
        end
        else begin
          state_var_NS = while_for_C_0;
        end
      end
      while_for_C_0 : begin
        fsm_output = 11'b00000000100;
        if ( while_for_C_0_tr0 ) begin
          state_var_NS = while_for_C_1;
        end
        else begin
          state_var_NS = while_for_for_C_0;
        end
      end
      while_for_for_C_0 : begin
        fsm_output = 11'b00000001000;
        state_var_NS = while_for_for_C_1;
      end
      while_for_for_C_1 : begin
        fsm_output = 11'b00000010000;
        state_var_NS = while_for_for_C_2;
      end
      while_for_for_C_2 : begin
        fsm_output = 11'b00000100000;
        state_var_NS = while_for_for_C_3;
      end
      while_for_for_C_3 : begin
        fsm_output = 11'b00001000000;
        state_var_NS = while_for_for_C_4;
      end
      while_for_for_C_4 : begin
        fsm_output = 11'b00010000000;
        state_var_NS = while_for_for_C_5;
      end
      while_for_for_C_5 : begin
        fsm_output = 11'b00100000000;
        if ( while_for_for_C_5_tr0 ) begin
          state_var_NS = while_for_C_1;
        end
        else begin
          state_var_NS = while_for_for_C_0;
        end
      end
      while_for_C_1 : begin
        fsm_output = 11'b01000000000;
        if ( while_for_C_1_tr0 ) begin
          state_var_NS = while_C_1;
        end
        else begin
          state_var_NS = while_for_C_0;
        end
      end
      while_C_1 : begin
        fsm_output = 11'b10000000000;
        state_var_NS = while_C_0;
      end
      // plm2vec_rlp_C_0
      default : begin
        fsm_output = 11'b00000000001;
        state_var_NS = while_C_0;
      end
    endcase
  end

  always @(posedge clk or negedge rst) begin
    if ( ~ rst ) begin
      state_var <= plm2vec_rlp_C_0;
    end
    else if ( plm2vec_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

