  // Interconnect Declarations for Component Instantiations 
  assign plm2vec_wten = plm2vec_wten_reg;
  assign plm2vec_wen = conf_info_ctrl_plm2vec_Pop_mioi_wen_comp_pff & ld2com_sync_Pop_mioi_wen_comp_pff
      & vec_in_a_Push_mioi_wen_comp_pff & vec_in_b_Push_mioi_wen_comp_pff & vec_out_Pop_mioi_wen_comp_pff
      & com2st_sync_Push_mioi_wen_comp_pff;
  always @(posedge clk or negedge rst) begin
    if ( ~ rst ) begin
      plm2vec_wten_reg <= 1'b0;
    end
    else begin
      plm2vec_wten_reg <= ~(conf_info_ctrl_plm2vec_Pop_mioi_wen_comp & ld2com_sync_Pop_mioi_wen_comp
          & vec_in_a_Push_mioi_wen_comp & vec_in_b_Push_mioi_wen_comp & vec_out_Pop_mioi_wen_comp
          & com2st_sync_Push_mioi_wen_comp);
